type counterTracer struct {
	counts map[string][]string // path -> sequence of ops
}

func (t *counterTracer) Enabled() bool                          { return true }
func (t *counterTracer) Config() topdown.TraceConfig            { return topdown.TraceConfig{} }
func (t *counterTracer) TraceEvent(evt topdown.Event) {
	rule, ok := evt.Node.(*ast.Rule)
	if !ok {
		return
	}
	path := ast.RulePath(rule)
	t.counts[path] = append(t.counts[path], string(evt.Op))
}

func run(name, query, module string, input map[string]any) {
	t := &counterTracer{counts: map[string][]string{}}
	rs, err := rego.New(
