		rego.Module("test.rego", module),
		rego.Input(input),
		rego.QueryTracer(t),
	).Eval(context.Background())
	fmt.Printf("=== %s (query=%s) err=%v\n", name, query, err)
	for path, ops := range t.counts {
		fmt.Printf("  %-30s %v\n", path, ops)
	}
	if rs != nil {
		fmt.Printf("  results: %v\n", rs)
	}
}

