+}
+
+// SuccessRate returns the ratio of successful evaluations to total
+// evaluations for the rule. It returns 0 if the rule was never evaluated.
+func (s *RuleStat) SuccessRate() float64 {
+	if s == nil || s.Evals == 0 {
+		return 0
+	}
+	return float64(s.Successes) / float64(s.Evals)
+}
+
+// String returns a human-readable representation of the rule statistics.
+func (s *RuleStat) String() string {
+	if s == nil {
+		return "<nil>"
+	}
+	return fmt.Sprintf("evals=%d successes=%d", s.Evals, s.Successes)
+}
+
+// evals returns the number of evaluations, treating a nil receiver as zero.
+func (s *RuleStat) evals() int {
+	if s == nil {
+		return 0
+	}
+	return s.Evals
+}
+
+// successes returns the number of successes, treating a nil receiver as zero.
+func (s *RuleStat) successes() int {
+	if s == nil {
+		return 0
+	}
+	return s.Successes
+}
+
+// EvalProfile is a collection of per-rule evaluation statistics gathered
+// during a single Rego evaluation. It maps each fully qualified rule path
+// (for example, "data.authz.allow") to the statistics recorded for it. Every
+// rule that is entered during evaluation is present, including rules that
+// never succeed.
+type EvalProfile map[string]*RuleStat
+
+// Stat returns the statistics recorded for the rule at the given fully
+// qualified path, or nil if the rule was not tracked.
+func (p EvalProfile) Stat(rule string) *RuleStat {
+	if p == nil {
+		return nil
+	}
+	return p[rule]
+}
+
+// RulePaths returns the tracked rule paths in sorted order. It returns nil if
+// no rules are tracked.
+func (p EvalProfile) RulePaths() []string {
+	if p == nil || len(p) == 0 {
+		return nil
+	}
+	paths := make([]string, 0, len(p))
+	for path := range p {
+		paths = append(paths, path)
+	}
+	sort.Strings(paths)
+	return paths
+}
+
+// SuccessRate returns the ratio of successes to evaluations for the rule at
+// the given path. It returns 0 if the rule is not tracked or was never
+// evaluated.
+func (p EvalProfile) SuccessRate(rule string) float64 {
+	if p == nil {
+		return 0
+	}
+	return p[rule].SuccessRate()
+}
+
+// OverallSuccessRate returns the aggregate ratio of successes to evaluations
+// across all tracked rules. It returns 0 if no rules were evaluated.
+func (p EvalProfile) OverallSuccessRate() float64 {
+	if p == nil {
+		return 0
+	}
+	var evals, successes int
+	for _, stat := range p {
+		evals += stat.evals()
+		successes += stat.successes()
+	}
+	if evals == 0 {
+		return 0
+	}
+	return float64(successes) / float64(evals)
+}
+
+// HotRules returns the sorted paths of rules that were entered at least
+// minEvals times. It returns nil if no rule qualifies.
+func (p EvalProfile) HotRules(minEvals int) []string {
+	if p == nil {
+		return nil
+	}
+	var rules []string
+	for path, stat := range p {
+		if stat.evals() >= minEvals {
+			rules = append(rules, path)
+		}
+	}
+	if len(rules) == 0 {
+		return nil
+	}
+	sort.Strings(rules)
+	return rules
+}
+
+// FailedRules returns the sorted paths of rules that were entered at least
+// once but never succeeded. It returns nil if no such rule is tracked.
+func (p EvalProfile) FailedRules() []string {
+	if p == nil {
+		return nil
+	}
+	var rules []string
+	for path, stat := range p {
+		if stat.evals() > 0 && stat.successes() == 0 {
+			rules = append(rules, path)
+		}
+	}
+	if len(rules) == 0 {
+		return nil
+	}
+	sort.Strings(rules)
+	return rules
+}
+
+// SucceededRules returns the sorted paths of rules that succeeded at least
+// once. It returns nil if no such rule is tracked.
+func (p EvalProfile) SucceededRules() []string {
+	if p == nil {
+		return nil
+	}
+	var rules []string
+	for path, stat := range p {
+		if stat.successes() > 0 {
+			rules = append(rules, path)
+		}
+	}
+	if len(rules) == 0 {
+		return nil
+	}
+	sort.Strings(rules)
+	return rules
+}
+
+// packagePath returns the package portion of a fully qualified rule path,
+// i.e. the path with its final rule name component removed. The path
+// "data.authz.allow" yields "data.authz".
+func packagePath(path string) string {
+	idx := strings.LastIndex(path, ".")
+	if idx <= 0 {
+		return path
+	}
+	return path[:idx]
+}
+
+// Packages returns the sorted, unique package names of all tracked rules. A
+// rule path such as "data.authz.allow" contributes the package "data.authz".
+// It returns nil if no rules are tracked.
+func (p EvalProfile) Packages() []string {
+	if p == nil {
+		return nil
+	}
+	seen := make(map[string]struct{})
+	for path := range p {
+		seen[packagePath(path)] = struct{}{}
+	}
+	if len(seen) == 0 {
+		return nil
+	}
+	pkgs := make([]string, 0, len(seen))
+	for pkg := range seen {
+		pkgs = append(pkgs, pkg)
+	}
+	sort.Strings(pkgs)
+	return pkgs
+}
+
+// copyStat returns a copy of the given statistics so callers can mutate the
+// copy without affecting the source profile.
+func copyStat(stat *RuleStat) *RuleStat {
+	if stat == nil {
+		return &RuleStat{}
+	}
+	return &RuleStat{
+		Evals:     stat.Evals,
+		Successes: stat.Successes,
+	}
+}
+
+// FilterByPackage returns a new profile containing only the rules whose
+// package matches pkg. The statistics are copied, so mutating the returned
+// profile does not affect the receiver. It returns nil if the receiver is nil
+// or no rule belongs to the package.
+func (p EvalProfile) FilterByPackage(pkg string) EvalProfile {
+	if p == nil {
+		return nil
+	}
+	result := make(EvalProfile)
+	for path, stat := range p {
+		if packagePath(path) == pkg {
+			result[path] = copyStat(stat)
+		}
+	}
+	if len(result) == 0 {
+		return nil
+	}
+	return result
+}
+
+// Merge combines this profile with other by summing the statistics of shared
+// rules. It returns nil if both profiles are nil, or the non-nil profile
+// unchanged if only one is nil. Neither input is modified.
+func (p EvalProfile) Merge(other EvalProfile) EvalProfile {
+	if p == nil {
+		return other
+	}
+	if other == nil {
+		return p
+	}
+	merged := make(EvalProfile, len(p)+len(other))
+	for path, stat := range other {
+		merged[path] = copyStat(stat)
+	}
+	for path, stat := range p {
+		if prev, ok := merged[path]; ok {
+			prev.Evals += stat.evals()
+			prev.Successes += stat.successes()
+		} else {
+			merged[path] = copyStat(stat)
+		}
+	}
+	return merged
+}
+
+// PackageStats returns the statistics aggregated per package across all
+// tracked rules. It returns nil if no rules are tracked.
+func (p EvalProfile) PackageStats() map[string]*RuleStat {
+	if p == nil {
+		return nil
+	}
+	stats := make(map[string]*RuleStat)
+	for path, stat := range p {
+		pkg := packagePath(path)
+		s := stats[pkg]
+		if s == nil {
+			s = &RuleStat{}
+			stats[pkg] = s
+		}
+		s.Evals += stat.evals()
+		s.Successes += stat.successes()
+	}
+	if len(stats) == 0 {
+		return nil
+	}
+	return stats
+}
+
+// ContainsRule reports whether the rule at the given fully qualified path is
+// tracked by the profile.
+func (p EvalProfile) ContainsRule(path string) bool {
+	if p == nil {
+		return false
+	}
+	_, ok := p[path]
+	return ok
+}
+
+// Summary returns a short, human-readable summary of the profile.
+func (p EvalProfile) Summary() string {
+	if p == nil {
+		return "profile: disabled"
+	}
+	var evals, successes int
+	for _, stat := range p {
+		evals += stat.evals()
+		successes += stat.successes()
+	}
+	return fmt.Sprintf("profile: %d rules, %d evals, %d successes", len(p), evals, successes)
+}
+
+// Equal reports whether the two profiles track the same rules with the same
+// statistics. Two nil profiles are equal.
+func (p EvalProfile) Equal(other EvalProfile) bool {
+	if p == nil {
+		return other == nil
+	}
+	if other == nil {
+		return false
+	}
+	if len(p) != len(other) {
+		return false
+	}
+	for path, stat := range p {
+		o, ok := other[path]
+		if !ok {
+			return false
+		}
+		if stat.evals() != o.evals() || stat.successes() != o.successes() {
+			return false
+		}
+	}
+	return true
+}
+
+// String returns a human-readable representation of the profile with one line
+// per tracked rule, sorted by path.
+func (p EvalProfile) String() string {
+	if p == nil {
+		return "<nil>"
+	}
+	var sb strings.Builder
+	sb.WriteString("Profile:\n")
+	for _, path := range p.RulePaths() {
+		stat := p[path]
+		fmt.Fprintf(&sb, "  %s: evals=%d successes=%d\n", path, stat.evals(), stat.successes())
+	}
+	return sb.String()
+}
+
+// RuleStatDelta describes how the statistics for a single rule differ between
+// two profiles. The deltas are computed as (other - receiver).
+type RuleStatDelta struct {
+	// EvalsDelta is the difference in the number of evaluations.
+	EvalsDelta int
+	// SuccessesDelta is the difference in the number of successes.
+	SuccessesDelta int
+}
+
+// ProfileDiff describes the difference between two profiles.
+type ProfileDiff struct {
+	// Added contains the rules that are tracked by the other profile but not
+	// by the receiver.
+	Added map[string]*RuleStat
+	// Removed contains the rules that are tracked by the receiver but not by
+	// the other profile.
+	Removed map[string]*RuleStat
+	// Changed contains the statistic deltas for rules tracked by both
+	// profiles whose statistics differ.
+	Changed map[string]*RuleStatDelta
+}
+
+// Diff compares the receiver profile to other and returns a description of
+// the differences. It returns nil if the receiver is nil.
+func (p EvalProfile) Diff(other EvalProfile) *ProfileDiff {
+	if p == nil {
+		return nil
+	}
+	diff := &ProfileDiff{}
+
+	for path, stat := range other {
+		if _, ok := p[path]; !ok {
+			if diff.Added == nil {
+				diff.Added = make(map[string]*RuleStat)
+			}
+			diff.Added[path] = copyStat(stat)
+		}
+	}
+
+	for path, stat := range p {
+		if _, ok := other[path]; !ok {
+			if diff.Removed == nil {
+				diff.Removed = make(map[string]*RuleStat)
+			}
+			diff.Removed[path] = copyStat(stat)
+		}
+	}
+
+	for path, stat := range p {
+		o, ok := other[path]
+		if !ok {
+			continue
+		}
+		if stat.evals() != o.evals() || stat.successes() != o.successes() {
+			if diff.Changed == nil {
+				diff.Changed = make(map[string]*RuleStatDelta)
+			}
+			delta := RuleStatDelta{
+				EvalsDelta:     o.evals() - stat.evals(),
+				SuccessesDelta: o.successes() - stat.successes(),
+			}
+			diff.Changed[path] = &delta
+		}
+	}
+
+	return diff
+}
+
+// HasChanges reports whether the diff contains any added, removed, or changed
+// rules. A nil diff has no changes.
+func (d *ProfileDiff) HasChanges() bool {
+	if d == nil {
+		return false
+	}
+	return len(d.Added) > 0 || len(d.Removed) > 0 || len(d.Changed) > 0
+}
+
+// Result defines the output of Rego evaluation.
+type Result struct {
+	Expressions []*ExpressionValue `json:"expressions"`
+	Bindings    Vars               `json:"bindings,omitempty"`
+	// Profile contains the per-rule evaluation statistics for the evaluation.
+	// It is nil unless rule profiling was enabled, either at construction
+	// time with EnableRuleProfile or per-evaluation with EvalRuleProfile.
+	Profile *EvalProfile `json:"profile,omitempty"`
+}
+
+// EvalRuleProfile returns an option that enables or disables rule evaluation
+// profiling for a single evaluation of a prepared query. A per-evaluation
+// setting overrides one set at construction time with EnableRuleProfile.
+func EvalRuleProfile(enabled bool) EvalOption {
+	return func(e *EvalContext) {
+		if enabled {
+			e.ruleProfiler = newRuleProfiler()
+		} else {
+			e.ruleProfiler = disabledRuleProfiler{}
+		}
+	}
+}
+
+// EnableRuleProfile returns an argument that enables or disables rule
+// evaluation profiling for all evaluations of this Rego object. When enabled,
+// the collected profile is attached to the Result of each evaluation.
+func EnableRuleProfile(enabled bool) func(r *Rego) {
+	return func(r *Rego) {
+		if enabled {
+			r.ruleProfiler = newRuleProfiler()
+		} else {
+			r.ruleProfiler = nil
+		}
+	}
+}
+
+// newRuleProfiler returns a rule profiler that collects rule statistics for a
+// single evaluation.
+func newRuleProfiler() ruleProfiler {
+	return &ruleProfilerImpl{profile: make(EvalProfile)}
+}
+
+// ruleProfilerImpl collects per-rule statistics for a single evaluation.
+type ruleProfilerImpl struct {
+	profile EvalProfile
+}
+
+func (p *ruleProfilerImpl) newEvaluation() ruleProfiler {
+	return newRuleProfiler()
+}
+
+func (p *ruleProfilerImpl) tracer() topdown.QueryTracer {
+	return &ruleProfileTracer{p: p}
+}
+
+func (p *ruleProfilerImpl) apply(result *Result) {
+	result.Profile = &p.profile
+}
+
+// disabledRuleProfiler is a no-op ruleProfiler used to explicitly disable rule
+// profiling for an evaluation.
+type disabledRuleProfiler struct{}
+
+func (disabledRuleProfiler) newEvaluation() ruleProfiler { return disabledRuleProfiler{} }
+func (disabledRuleProfiler) tracer() topdown.QueryTracer { return nil }
+func (disabledRuleProfiler) apply(*Result)               {}
+
+// ruleProfileTracer feeds rule enter/exit trace events into a
+// ruleProfilerImpl.
+type ruleProfileTracer struct {
+	p *ruleProfilerImpl
+}
+
+func (t *ruleProfileTracer) Enabled() bool {
+	return true
+}
+
+func (t *ruleProfileTracer) Config() topdown.TraceConfig {
+	return topdown.TraceConfig{}
+}
+
+func (t *ruleProfileTracer) TraceEvent(evt topdown.Event) {
+	rule, ok := evt.Node.(*ast.Rule)
+	if !ok {
+		return
+	}
+	path := ast.RulePath(rule)
+	stat := t.p.profile[path]
+	if stat == nil {
+		stat = &RuleStat{}
+		t.p.profile[path] = stat
+	}
+	switch evt.Op {
+	case topdown.EnterOp:
+		stat.Evals++
+	case topdown.ExitOp:
+		stat.Successes++
+	}
+}
